@Override
	public void inventoryTick(ItemStack staff, Level level, Entity entity, int itemSlot, boolean isSelected) {
		super.inventoryTick(staff, level, entity, itemSlot, isSelected);

		if (level.isClientSide() || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 2 != 0) {
			return;
		}

		if (isEnabled(staff)) {
			freezeBlocks(staff, level, player);
		}
		meltBlocks(staff, level, player);
	}

private void freezeBlocks(ItemStack staff, Level level, Player player) {
		BlockPos playerPos = player.blockPosition();
		BlockPos.betweenClosed(playerPos.offset(-2, -1, -2), playerPos.offset(2, -1, 2)).forEach(pos -> {
			if (Math.abs(playerPos.getX() - pos.getX()) == 2 && Math.abs(playerPos.getZ() - pos.getZ()) == 2) {
				return;
			}
			doFreezeCheck(staff, pos.immutable(), level);
		});
	}

private void meltBlocks(ItemStack staff, Level level, Player player) {
		if (!level.isClientSide) {
			BlockPos playerPos = player.blockPosition();
			for (BlockPos pos : getBlockLocations(staff)) {
				if (!level.isLoaded(pos)) {
					continue;
				}

				int xOff = Math.abs(playerPos.getX() - pos.getX());
				int yOff = Math.abs(playerPos.getY() - pos.getY());
				int zOff = Math.abs(playerPos.getZ() - pos.getZ());

				if (xOff < 3 && yOff < 3 && zOff < 3 && !(xOff == 2 && zOff == 2)) {
					continue;
				}

				doThawCheck(staff, pos, level);
			}
		}
	}

private Set<BlockPos> getBlockLocations(ItemStack stack) {
		return stack.getOrDefault(ModDataComponents.FROZEN_POSITIONS, new HashSet<>());
	}

private void doFreezeCheck(ItemStack stack, BlockPos pos, Level level) {
		BlockState blockState = level.getBlockState(pos);
		if (blockState.getBlock() == Blocks.WATER && blockState.getValue(LiquidBlock.LEVEL) == 0 && level.isEmptyBlock(pos.above())) {
			addFrozenBlockToList(stack, pos);
			level.setBlockAndUpdate(pos, Blocks.PACKED_ICE.defaultBlockState());
			for (int particleNum = level.random.nextInt(3); particleNum < 2; ++particleNum) {
				float xVel = level.random.nextFloat();
				float yVel = level.random.nextFloat() + 0.5F;
				float zVel = level.random.nextFloat();
				level.addParticle(ICE_PARTICLE, pos.getX() + xVel, pos.getY() + yVel, pos.getZ() + zVel, 0.75F, 0.75F, 1.0F);
			}
		} else if (blockState.getBlock() == Blocks.LAVA && blockState.getValue(LiquidBlock.LEVEL) == 0) {
			addFrozenBlockToList(stack, pos);
			level.setBlockAndUpdate(pos, Blocks.OBSIDIAN.defaultBlockState());
			for (int particleNum = level.random.nextInt(3); particleNum < 2; ++particleNum) {
				float xVel = level.random.nextFloat();
				float yVel = level.random.nextFloat() + 0.5F;
				float zVel = level.random.nextFloat();
				level.addParticle(level.random.nextInt(3) == 0 ? ParticleTypes.LARGE_SMOKE : ParticleTypes.SMOKE, pos.getX() + xVel, pos.getY() + yVel,
						pos.getZ() + zVel, 0.0D, 0.2D, 0.0D);
			}
		}
	}

private void doThawCheck(ItemStack stack, BlockPos pos, Level level) {
		BlockState blockState = level.getBlockState(pos);
		if (blockState == Blocks.PACKED_ICE.defaultBlockState()) {
			if (removeFrozenBlockFromList(stack, pos)) {
				level.setBlockAndUpdate(pos, Blocks.WATER.defaultBlockState());
				for (int particleNum = level.random.nextInt(3); particleNum < 2; ++particleNum) {
					float xVel = level.random.nextFloat();
					float yVel = level.random.nextFloat() + 0.5F;
					float zVel = level.random.nextFloat();
					level.addParticle(level.random.nextInt(3) == 0 ? ParticleTypes.LARGE_SMOKE : ParticleTypes.SMOKE, pos.getX() + xVel, pos.getY() + yVel,
							pos.getZ() + zVel, 0.0D, 0.2D, 0.0D);
				}
			}
		} else if (blockState == Blocks.OBSIDIAN.defaultBlockState() && removeFrozenBlockFromList(stack, pos)) {
			level.setBlockAndUpdate(pos, Blocks.LAVA.defaultBlockState());
			for (int particleNum = level.random.nextInt(3); particleNum < 2; ++particleNum) {
				float xVel = level.random.nextFloat();
				float yVel = level.random.nextFloat() + 0.5F;
				float zVel = level.random.nextFloat();
				level.addParticle(DustParticleOptions.REDSTONE, pos.getX() + xVel, pos.getY() + yVel, pos.getZ() + zVel, 0F, 0.2F, 0F);
			}
		}
	}

private void addFrozenBlockToList(ItemStack stack, BlockPos pos) {
		HashSet<BlockPos> frozenPositions = new HashSet<>(getBlockLocations(stack));
		frozenPositions.add(pos);

		stack.set(ModDataComponents.FROZEN_POSITIONS, ImmutableSet.copyOf(frozenPositions));
	}

private boolean removeFrozenBlockFromList(ItemStack stack, BlockPos pos) {
		HashSet<BlockPos> frozenPositions = new HashSet<>(getBlockLocations(stack));
		if (frozenPositions.remove(pos)) {
			stack.set(ModDataComponents.FROZEN_POSITIONS, ImmutableSet.copyOf(frozenPositions));
			return true;
		}
		return false;
	}

@Override
	public void inventoryTick(ItemStack stack, Level level, Entity entity, int i, boolean f) {
		if (level.isClientSide() || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % EFFECT_COOLDOWN != 0) {
			return;
		}

		doFireballAbsorbEffect(stack, player);

		if (!isEnabled(stack)) {
			doExtinguishEffect(player);
		} else {
			scanForFireChargeAndBlazePowder(stack, player);
		}
	}

private void doFireballAbsorbEffect(ItemStack stack, Player player) {
		if (player.level().isClientSide) {
			return;
		}
		absorbGhastFireballs(stack, player);
		absorbBlazeFireballs(stack, player);
	}

private void absorbBlazeFireballs(ItemStack stack, Player player) {
		List<SmallFireball> blazeFireballs = player.level().getEntitiesOfClass(SmallFireball.class, player.getBoundingBox().inflate(3));
		for (SmallFireball fireball : blazeFireballs) {
			if (fireball.getOwner() == player) {
				continue;
			}
			int pointsToAdd = getBlazeAbsorbWorth();
			if (pointsToAdd > 0 && addPartialCharge(stack, BLAZE_POWDER_SLOT, pointsToAdd, getBlazePowderLimit(), new ItemStack(Items.BLAZE_POWDER))) {
				for (int particles = 0; particles < 4; particles++) {
					player.level().addParticle(DustParticleOptions.REDSTONE, fireball.getX(), fireball.getY(), fireball.getZ(), 0.0D, 1.0D, 1.0D);
				}
				player.level().playLocalSound(fireball.getX(), fireball.getY(), fireball.getZ(), SoundEvents.LAVA_EXTINGUISH, SoundSource.BLOCKS, 0.5F,
						2.6F + RandHelper.getRandomMinusOneToOne(player.level().random) * 0.8F, false);
			}
			fireball.discard();
		}
	}

private void absorbGhastFireballs(ItemStack stack, Player player) {
		List<LargeFireball> ghastFireballs = player.level().getEntitiesOfClass(LargeFireball.class, player.getBoundingBox().inflate(4));
		for (LargeFireball fireball : ghastFireballs) {
			if (fireball.getOwner() != player) {
				int pointsToAdd = getGhastAbsorbWorth();
				if (pointsToAdd > 0 && addPartialCharge(stack, FIRE_CHARGE_SLOT, pointsToAdd, getFireChargeLimit(), new ItemStack(Items.FIRE_CHARGE))) {
					player.level().playLocalSound(fireball.getX(), fireball.getY(), fireball.getZ(), SoundEvents.LAVA_EXTINGUISH, SoundSource.BLOCKS, 0.5F,
							2.6F + RandHelper.getRandomMinusOneToOne(player.level().random) * 0.8F, false);
				}
				fireball.discard();
			}
		}
	}

protected boolean addPartialCharge(ItemStack containerStack, int slot, int chargeToAdd, int pointLimit, ItemStack chargeStack) {
		int worth = getSlotWorth(slot);
		int storedCharge = getMigratedStoredCharge(containerStack, slot);
		int currentCharge = getPartialCharge(containerStack, slot);
		long totalCharge = (long) storedCharge * worth + currentCharge;
		int remainingCapacity = Math.toIntExact(Math.max(pointLimit - totalCharge, 0));
		int acceptedCharge = Math.min(Math.max(chargeToAdd, 0), remainingCapacity);
		int updatedPartialCharge = currentCharge + acceptedCharge;
		if (updatedPartialCharge >= worth) {
			int maxPhysicalCharge = pointLimit / worth;
			int fullCharges = Math.min(updatedPartialCharge / worth, Math.max(maxPhysicalCharge - storedCharge, 0));
			if (fullCharges > 0) {
				ItemStack storedChargeStack = chargeStack.copy();
				storedChargeStack.setCount(fullCharges);
				addStoredCharge(containerStack, slot, fullCharges, storedChargeStack);
				updatedPartialCharge -= fullCharges * worth;
			}
		}
		setPartialCharge(containerStack, slot, updatedPartialCharge);
		return acceptedCharge > 0;
	}

@Override
    public boolean checkPreCastConditions(Level level, int spellLevel, LivingEntity entity, MagicData playerMagicData) {
        if (!(entity instanceof ServerPlayer serverPlayer)) {
            return false;
        }
        if (level.dimension().equals(PocketDimensionManager.POCKET_DIMENSION)) {
            serverPlayer.connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("ui.irons_spellbooks.cast_error_dimension").withStyle(ChatFormatting.RED)));
            return false;
        }
        if (entity.getCombatTracker().inCombat) {
            serverPlayer.displayClientMessage(Component.translatable("ui.irons_spellbooks.cast_error_combat").withStyle(ChatFormatting.RED), true);
            return false;
        }
        return true;
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
        if (entity instanceof ServerPlayer serverPlayer) {
            PortalData portalData = new PortalData();
            portalData.setPortalDuration(20 * 60);
            portalData.firstPortal(serverPlayer.getUUID(), PortalPos.of(serverPlayer.level.dimension(), serverPlayer.position(), serverPlayer.getYRot()));

            PocketDimensionManager.INSTANCE.maybeGeneratePocketRoom(serverPlayer);
            BlockPos portalPos = PocketDimensionManager.INSTANCE.findPortalForStructure(serverPlayer.serverLevel(), PocketDimensionManager.INSTANCE.structurePosForPlayer(serverPlayer));
            ServerLevel pocketLevel = serverPlayer.getServer().getLevel(PocketDimensionManager.POCKET_DIMENSION);
            var portal = pocketLevel.getBlockEntity(portalPos);
            if (portal instanceof PortalFrameBlockEntity portalFrameBlockEntity) {
                Vec3 particlePos = serverPlayer.getBoundingBox().getCenter();
                MagicManager.spawnParticles(level, ParticleTypes.SMOKE, particlePos.x, particlePos.y, particlePos.z, 100, 0.1, 0.2, 0.1, 0.1, false);

                var uuid = portalFrameBlockEntity.getUUID();
                portalData.secondPortal(uuid, PortalPos.of(PocketDimensionManager.POCKET_DIMENSION, portalPos.getBottomCenter(), 180));
                PortalManager.INSTANCE.addPortalData(uuid, portalData);
                portalFrameBlockEntity.setChanged();
                PortalManager.INSTANCE.addDirectPortalCooldown(serverPlayer, uuid); // Manually add cooldown as if the player used the portal to help prevent immediately teleporting back
                Scroll.attemptRemoveScrollAfterCast(serverPlayer); // Manually call this because this serverplayer will be removed from the level after the spellcast
                serverPlayer.stopRiding();
                serverPlayer.changeDimension(new DimensionTransition(pocketLevel, portalData.globalPos2.pos(), Vec3.ZERO, portalData.globalPos2.rotation(), serverPlayer.getXRot(), DimensionTransition.DO_NOTHING));

            }
        }
    }

public void addDirectPortalCooldown(Entity entity, UUID portalId) {
        var playerMap = cooldownLookup.computeIfAbsent(portalId, k -> new HashMap<>());
        playerMap.put(entity.getUUID(), new AtomicInteger(cooldownTicks));
    }

public void processCooldownTick(UUID portalUUID, int delta) {
        var playerCooldownsForPortal = cooldownLookup.get(portalUUID);
        if (playerCooldownsForPortal != null) {
            playerCooldownsForPortal.entrySet()
                    .stream()
                    .filter(item -> item.getValue().addAndGet(delta) <= 0)
                    .toList()
                    .forEach(itemToRemove -> playerCooldownsForPortal.remove(itemToRemove.getKey()));
        }
    }

public void processDelayCooldown(UUID portalUUID, UUID playerUUID, int delta) {
        var playerCooldownsForPortal = cooldownLookup.get(portalUUID);
        if (playerCooldownsForPortal != null) {
            var cooldown = playerCooldownsForPortal.get(playerUUID);
            if (cooldown != null) {
                cooldown.addAndGet(delta);
            }
        }
    }

public boolean canUsePortal(PortalEntity portalEntity, Entity entity) {
        //IronsSpellbooks.LOGGER.debug("canUsePortal portal:{}, entity:{}", portalEntity.getUUID(), entity);
        if (portalEntity == null || entity == null) {
            return false;
        }
        return canUsePortal(portalEntity.getUUID(), entity);
    }

@Override
    public CompoundTag serializeNBT(HolderLookup.Provider pRegistries) {
        //Ignoring cooldowns. Too short to care about persisting them

        var tag = new CompoundTag();
        var portalLookupTag = new ListTag();

        if (!portalLookup.isEmpty()) {
            portalLookupTag.addAll(portalLookup.entrySet().stream().map(entry -> {
                CompoundTag itemTag = new CompoundTag();
                itemTag.putUUID("key", entry.getKey());
                itemTag.put("value", entry.getValue().serializeNBT(pRegistries));
                return itemTag;
            }).toList());
        }

        tag.put("portalLookup", portalLookupTag);
        return tag;
    }

public void killPortal(UUID portalUUID, @Nullable UUID ownerUUID) {
        var removedPortalData = portalLookup.remove(portalUUID);

        if (removedPortalData != null) {
            if (removedPortalData.portalEntityId2 == null || removedPortalData.globalPos2 == null) {
                tryCancelRecast(portalUUID, ownerUUID);
            } else {
                var connectedPortalUUID = removedPortalData.getConnectedPortalUUID(portalUUID);
                if (connectedPortalUUID != null) {
                    removedPortalData = portalLookup.remove(connectedPortalUUID);

                    removedPortalData.getConnectedPortalPos(portalUUID).ifPresent(globalPos -> {
                        var level = IronsSpellbooks.MCS.getLevel(globalPos.dimension());
                        if (level != null) {
                            var connectedPortalToRemove = level.getEntity(connectedPortalUUID);
                            if (connectedPortalToRemove != null) {
                                connectedPortalToRemove.discard();
                            }
                        }
                    });
                    cooldownLookup.remove(connectedPortalUUID);
                }
            }
        }

        cooldownLookup.remove(portalUUID);
        IronsDataStorage.INSTANCE.setDirty();
    }

@Override
    public void tick() {
        if (level.isClientSide) {
            Vec3 center = this.getBoundingBox().getCenter();
            for (int i = 0; i < 2; i++) {
                level.addParticle(ParticleHelper.PORTAL_FRAME, center.x, center.y, center.z, 1f, 2.1f, this.getYRot());
            }
            return;
        }

        PortalManager.INSTANCE.processCooldownTick(uuid, -1);
        checkForEntitiesToTeleport();

        if (--ticksToLive <= 0) {
            discard();
        }
    }

public void checkForEntitiesToTeleport() {
        if (this.level.isClientSide) return;
        level.getEntities((Entity) null, this.getBoundingBox(), (entity -> !entity.getType().is(ModTags.CANT_USE_PORTAL) && (entity.isPickable() || entity instanceof Projectile) && !entity.isVehicle() && !entity.isSpectator())).forEach(entity -> {
            //IronsSpellbooks.LOGGER.debug("PortalEntity: entity near portal:{}, portal:{}", entity, uuid);

            PortalManager.INSTANCE.processDelayCooldown(uuid, entity.getUUID(), 1);

            if (PortalManager.INSTANCE.canUsePortal(this, entity)) {
                //IronsSpellbooks.LOGGER.debug("PortalEntity: teleport entity:{} portal:{}", entity, uuid);

                PortalManager.INSTANCE.addPortalCooldown(entity, uuid);

                var portalData = PortalManager.INSTANCE.getPortalData(this);
                portalData.getConnectedPortalPos(uuid).ifPresent(portalPos -> {
                    Vec3 destination = portalPos.pos().add(0, entity.getY() - this.getY(), 0);
                    entity.setYRot(portalPos.rotation());
                    this.level.playSound(null, this.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.NEUTRAL, 1f, 1f);
                    if (level.dimension().equals(portalPos.dimension())) {
                        entity.teleportTo(destination.x, destination.y + .1, destination.z);
                        var delta = entity.getDeltaMovement();
                        float hspeed = (float) Math.sqrt(delta.x * delta.x + delta.z * delta.z);
                        float f = portalPos.rotation() * Mth.DEG_TO_RAD;
                        entity.setDeltaMovement(-Mth.sin(f) * hspeed, delta.y, Mth.cos(f) * hspeed);
                        handleLoopTracking(entity);
                    } else {
                        //IronsSpellbooks.LOGGER.debug("PortalEntity: teleport entity:{} to dimension: {}", entity, portalPos.dimension());
                        var server = level.getServer();
                        if (server != null) {
                            var dim = server.getLevel(portalPos.dimension());
                            if (dim != null) {
                                entity.changeDimension(new DimensionTransition(dim, destination, Vec3.ZERO, entity.getYRot(), entity.getXRot(), DimensionTransition.DO_NOTHING));
                            }
                        }
                    }
                    this.level.playSound(null, destination.x, destination.y, destination.z, SoundEvents.ENDERMAN_TELEPORT, SoundSource.NEUTRAL, 1f, 1f);
                });
            }
        });
    }

private void handleLoopTracking(Entity entity) {
        var trackerData = loopTrackerLookup.get(entity.getUUID());
        if (trackerData == null) {
            trackerData = new LoopTrackerData(level.getGameTime(), 1);
            loopTrackerLookup.put(entity.getUUID(), trackerData);
        } else {
            IronsSpellbooks.LOGGER.debug("looping");
            if (++trackerData.loopCount > loopMax && level.getGameTime() - trackerData.gameTick <= loopTickWindow) {
                if (Objects.equals(getOwnerUUID(), entity.getUUID())) {
                    entity.hurt(new PortalDamageSource(entity.level().damageSources().genericKill().typeHolder(), entity), Float.MAX_VALUE);
                    if (entity instanceof LivingEntity livingEntity && Float.isNaN(livingEntity.getHealth())) {
                        livingEntity.setHealth(0.0f);
                    }
                }
                discard();
            } else if (level.getGameTime() - trackerData.gameTick > loopTickWindow) {
                //Cleanup old tracking information
                loopTrackerLookup.remove(entity.getUUID());
            }
        }
    }

@Override
    public void onRemovedFromLevel() {
        if (!level.isClientSide && clearPortalOnDeath()) {
            var removalReason = getRemovalReason();
            if (removalReason != null && removalReason.shouldDestroy()) {
                PortalManager.INSTANCE.killPortal(uuid, getOwnerUUID());
            }
            MagicManager.spawnParticles(level, new SparkParticleOptions(new Vector3f(.5f, .05f, .6f)), getX(), getY() + 0.5, getZ(), 25, .2, .4, .2, .3, false);
        }
        super.onRemovedFromLevel();
    }

@Override
    protected void readAdditionalSaveData(CompoundTag compoundTag) {
        if (compoundTag.contains("ownerUUID")) {
            setOwnerUUID(compoundTag.getUUID("ownerUUID"));
        }

        if (compoundTag.contains("ticksToLive")) {
            ticksToLive = compoundTag.getLong("ticksToLive");
        }

        var portalData = PortalManager.INSTANCE.getPortalData(this);

        if (portalData == null) {
            ticksToLive = 0;
        } else {
            if (portalData.portalEntityId1 != null && portalData.portalEntityId2 != null) {
                setPortalConnected();
            }
        }
    }

@Override
    protected void addAdditionalSaveData(CompoundTag compoundTag) {
        compoundTag.putLong("ticksToLive", ticksToLive);
        if (getOwnerUUID() != null) {
            compoundTag.putUUID("ownerUUID", getOwnerUUID());
        }
    }

@Override
	public void onUpdate() {
		if (!getEntityWorld().isRemote) {
			if (isTemporary() && ticksExisted > 20)
				setDead();
			if (getEntityWorld().getTotalWorldTime() % 5 == 0) {
				if (!isHanging())
					checkArea();
				else
					checkBlockAbove();
			}
		}

		if (getEntityWorld().isRemote)
			dustParticles();
	}

private void checkBlockAbove() {
		if (getEntityWorld().isAirBlock(getPosition().up())) {
			Entity spawn = getEntitySpawned();
			if (spawn != null) {
				performPreSpawnaction(this, spawn);
				if (!spawn.isDead) // just in case of pre-emptive removal
					getEntityWorld().spawnEntity(spawn);
			}
			if (!isDead && isSingleUse())
				setDead();
		}
	}

@Override
	protected void performPreSpawnaction(Entity targetEntity, Entity entitySpawned) {
		((EntityFallingBlock)entitySpawned).setHurtEntities(true);
		 if (!getEntityWorld().isRemote) {
			 targetEntity.getEntityWorld().playSound(null, targetEntity.getPosition(), SoundRegistry.ROOF_COLLAPSE, SoundCategory.BLOCKS, 0.5F, 1.0F);
		 }
	}

@Override
	protected Entity getEntitySpawned() {
		if(getBlockType(getEntityWorld(), getPosition()).getBlock() != null) {
			EntityFallingBlock entity = new EntityFallingBlock(getEntityWorld(), posX, posY, posZ, getBlockType(getEntityWorld(), getPosition()));
			entity.shouldDropItem = false;
			return entity;
		}
		return null;
	}

@Override
	protected boolean isSingleUse() {
		return true;
	}

@Override
	public void readEntityFromNBT(NBTTagCompound nbt) {
		super.readEntityFromNBT(nbt);
		setWalkway(nbt.getBoolean("walk_way"));
		setHanging(nbt.getBoolean("hanging"));
		setTemporary(nbt.getBoolean("temp"));
	}

@Override
	public void writeEntityToNBT(NBTTagCompound nbt) {
		super.writeEntityToNBT(nbt);
		nbt.setBoolean("walk_way", isWalkway());
		nbt.setBoolean("hanging", isHanging());
		nbt.setBoolean("temp", isTemporary());
	}

@Nullable
	protected Entity checkArea() {
		if (!getEntityWorld().isRemote && getEntityWorld().getDifficulty() != EnumDifficulty.PEACEFUL) {
			List<EntityLivingBase> list = getEntityWorld().getEntitiesWithinAABB(EntityLivingBase.class, proximityBox());
			for (int entityCount = 0; entityCount < list.size(); entityCount++) {
				Entity entity = list.get(entityCount);
				if (entity != null)
					if (entity instanceof EntityPlayer && !((EntityPlayer) entity).isSpectator() && !((EntityPlayer) entity).isCreative()) {
						if (canSneakPast() && entity.isSneaking())
							return null;
						else if (checkSight() && !canEntityBeSeen(entity))
							return null;
						else {
							for (int count = 0; count < getEntitySpawnCount(); count++) {
								Entity spawn = getEntitySpawned();
								if (spawn != null) {
									performPreSpawnaction(entity, spawn);
									if (!spawn.isDead) // just in case of pre-emptive removal
										getEntityWorld().spawnEntity(spawn);
									performPostSpawnaction(entity, spawn);
								}
							}
							if (!isDead && isSingleUse())
								setDead();
						}
					}
			}
		}
		return null;
	}
